/**
 * Shared cent-to-string conversion.
 *
 * Returns the sign (a single leading '-' for negative amounts), the absolute
 * whole currency units and exactly two fraction digits, with no currency
 * symbol.
 */
export function formatAmount(cents: number): string {
  const absolute = Math.abs(cents);
  const sign = cents < 0 ? '-' : '';
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}

